83	func cmdQuery(dataFile string, argv []string, stdout, stderr io.Writer) int {
84		fs := newFlagSet("query", stderr)
85		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
86		id := fs.String("id", "", "要查询的包裹编号")
87		if ok, code := parseFlags(fs, argv, stdout, stderr, printQueryHelp); !ok {
88			return code
89		}
90	
91		cleanIDVal, err := cleanID("包裹编号", *id)
92		if err != nil {
93			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
94			return exitBusiness
95		}
96	
97		store, err := Open(dataFile)
98		if err != nil {
99			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
100			return exitBusiness
101		}
102		p, err := store.Query(cleanIDVal)
103		if err != nil {
104			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
105			return exitBusiness
106		}
107	
108		fmt.Fprintf(stdout, "包裹编号: %s\n当前站点: %s\n当前状态: %s\n", p.ID, p.Station, p.Status)
109		if f := store.ActiveFreeze(cleanIDVal); f != nil {
110			fmt.Fprintf(stdout, "当前未解除异常: 异常单号: %s    原因: %s    冻结时间: %s\n",
111				f.Incident, f.Reason, f.Time.Format(timeFmt))
112		}
113		fmt.Fprintf(stdout, "轨迹（按提交顺序，共 %d 条）:\n", len(p.Trail))
114		for i, e := range p.Trail {
115			switch e.Op {
116			case "退回":
117				fmt.Fprintf(stdout, "  %d. 操作: 退回    源站: %s    目的站: %s    退回请求号: %s    原交接请求号: %s    原因: %s    时间: %s\n",
118					i+1, e.From, e.Station, e.Request, e.RefRequest, e.Reason, e.Time.Format(timeFmt))
119			case "出站":
120				fmt.Fprintf(stdout, "  %d. 操作: 出站    站点: %s    批次号: %s    配送员: %s    时间: %s\n",
121					i+1, e.Station, e.Batch, e.Courier, e.Time.Format(timeFmt))
122			case "回执":
123				if e.Result == resultFailed {
124					fmt.Fprintf(stdout, "  %d. 操作: 回执    站点: %s    批次号: %s    结果: %s    原因: %s    请求号: %s    时间: %s\n",
125						i+1, e.Station, e.Batch, e.Result, e.Reason, e.Request, e.Time.Format(timeFmt))
126				} else {
127					fmt.Fprintf(stdout, "  %d. 操作: 回执    站点: %s    批次号: %s    结果: %s    请求号: %s    时间: %s\n",
128						i+1, e.Station, e.Batch, e.Result, e.Request, e.Time.Format(timeFmt))
129				}
130			case "冻结":
131				fmt.Fprintf(stdout, "  %d. 操作: 冻结    站点: %s    异常单号: %s    原因: %s    时间: %s\n",
132					i+1, e.Station, e.Incident, e.Reason, e.Time.Format(timeFmt))
133			case "解除冻结":
134				fmt.Fprintf(stdout, "  %d. 操作: 解除冻结    站点: %s    异常单号: %s    解除请求号: %s    处理说明: %s    时间: %s\n",
135					i+1, e.Station, e.Incident, e.Request, e.Note, e.Time.Format(timeFmt))
136			default:
137				req := e.Request
138				if req == "" {
139					req = "-"
140				}
141				fmt.Fprintf(stdout, "  %d. 操作: %s    站点: %s    请求号: %s    时间: %s\n",
142					i+1, e.Op, e.Station, req, e.Time.Format(timeFmt))
143			}
144		}
145		return exitOK
146	}
