148	func cmdHandoff(dataFile string, argv []string, stdout, stderr io.Writer) int {
149		fs := newFlagSet("handoff", stderr)
150		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
151		request := fs.String("request", "", "交接请求号（用于去重）")
152		from := fs.String("from", "", "源站点")
153		to := fs.String("to", "", "目的站点")
154		var parcels stringList
155		fs.Var(&parcels, "parcel", "包裹编号，可重复指定；集合不可为空或含重复编号")
156		if ok, code := parseFlags(fs, argv, stdout, stderr, printHandoffHelp); !ok {
157			return code
158		}
159	
160		cleanReq, err := cleanID("请求号", *request)
161		if err != nil {
162			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
163			return exitBusiness
164		}
165		cleanFrom, err := cleanID("源站点", *from)
166		if err != nil {
167			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
168			return exitBusiness
169		}
170		cleanTo, err := cleanID("目的站点", *to)
171		if err != nil {
172			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
173			return exitBusiness
174		}
175		if len(parcels) == 0 {
176			fmt.Fprintf(stderr, "%s handoff: 包裹集合不可为空，至少需要一个 --parcel\n", appName)
177			return exitBusiness
178		}
179		cleanParcels := make([]string, 0, len(parcels))
180		seen := make(map[string]bool, len(parcels))
181		for _, raw := range parcels {
182			id, err := cleanID("包裹编号", raw)
183			if err != nil {
184				fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
185				return exitBusiness
186			}
187			if seen[id] {
188				fmt.Fprintf(stderr, "%s handoff: 包裹集合中编号 %q 重复\n", appName, id)
189				return exitBusiness
190			}
191			seen[id] = true
192			cleanParcels = append(cleanParcels, id)
193		}
194		if cleanFrom == cleanTo {
195			fmt.Fprintf(stderr, "%s handoff: 源站点与目的站点不能相同（均为 %q）\n", appName, cleanFrom)
196			return exitBusiness
197		}
198	
199		store, err := Open(dataFile)
200		if err != nil {
201			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
202			return exitBusiness
203		}
204		result, replayed, err := store.Handoff(cleanReq, cleanFrom, cleanTo, cleanParcels, now())
205		if err != nil {
206			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
207			return exitBusiness
208		}
209	
210		headline := "交接成功"
211		if replayed {
212			headline = "交接成功（请求号重复提交，返回首次保存的结果，未再追加轨迹）"
213		}
214		fmt.Fprintf(stdout, "%s\n请求号: %s\n源站点: %s\n目的站点: %s\n包裹（%d 件）:\n",
215			headline, result.Request, result.From, result.To, len(result.Parcels))
216		for _, id := range result.Parcels {
217			fmt.Fprintf(stdout, "  - %s\n", id)
218		}
219		fmt.Fprintf(stdout, "发生时间: %s\n", result.Time.Format(timeFmt))
220		return exitOK
221	}
