273	// cleanParcelList 清洗并校验可重复的 --parcel 参数：逐个去除两端空白、
274	// 不可为空、集合不可为空且编号不可重复。
275	func cleanParcelList(raw []string) ([]string, error) {
276		if len(raw) == 0 {
277			return nil, fmt.Errorf("包裹集合不可为空，至少需要一个 --parcel")
278		}
279		clean := make([]string, 0, len(raw))
280		seen := make(map[string]bool, len(raw))
281		for _, v := range raw {
282			id, err := cleanID("包裹编号", v)
283			if err != nil {
284				return nil, err
285			}
286			if seen[id] {
287				return nil, fmt.Errorf("包裹集合中编号 %q 重复", id)
288			}
289			seen[id] = true
290			clean = append(clean, id)
291		}
292		return clean, nil
293	}
