352	func cmdReceipt(dataFile string, argv []string, stdout, stderr io.Writer) int {
353		fs := newFlagSet("receipt", stderr)
354		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
355		request := fs.String("request", "", "回执请求号（用于去重）")
356		batch := fs.String("batch", "", "配送批次号")
357		parcel := fs.String("parcel", "", "包裹编号")
358		result := fs.String("result", "", "回执结果：签收 或 失败")
359		reason := fs.String("reason", "", "失败原因（结果为失败时必填，签收时不可带）")
360		if ok, code := parseFlags(fs, argv, stdout, stderr, printReceiptHelp); !ok {
361			return code
362		}
363	
364		cleanReq, err := cleanID("回执请求号", *request)
365		if err != nil {
366			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
367			return exitBusiness
368		}
369		cleanBatch, err := cleanID("批次号", *batch)
370		if err != nil {
371			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
372			return exitBusiness
373		}
374		cleanParcel, err := cleanID("包裹编号", *parcel)
375		if err != nil {
376			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
377			return exitBusiness
378		}
379		cleanResult, err := cleanID("回执结果", *result)
380		if err != nil {
381			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
382			return exitBusiness
383		}
384		if cleanResult != resultSigned && cleanResult != resultFailed {
385			fmt.Fprintf(stderr, "%s receipt: 回执结果只能是 %q 或 %q，得到 %q\n", appName, resultSigned, resultFailed, cleanResult)
386			return exitBusiness
387		}
388		cleanReason := strings.TrimSpace(*reason)
389		if cleanResult == resultFailed && cleanReason == "" {
390			fmt.Fprintf(stderr, "%s receipt: 结果为失败时原因不可为空或仅含空白\n", appName)
391			return exitBusiness
392		}
393		if cleanResult == resultSigned && cleanReason != "" {
394			fmt.Fprintf(stderr, "%s receipt: 结果为签收时不可带原因\n", appName)
395			return exitBusiness
396		}
397	
398		store, err := Open(dataFile)
399		if err != nil {
400			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
401			return exitBusiness
402		}
403		res, replayed, err := store.Receipt(cleanReq, cleanBatch, cleanParcel, cleanResult, cleanReason, now())
404		if err != nil {
405			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
406			return exitBusiness
407		}
408	
409		headline := "回执成功"
410		if replayed {
411			headline = "回执成功（请求号重复提交，返回首次保存的结果，未再追加轨迹）"
412		}
413		fmt.Fprintf(stdout, "%s\n请求号: %s\n批次号: %s\n包裹编号: %s\n结果: %s\n",
414			headline, res.Request, res.Batch, res.Parcel, res.Result)
415		if res.Result == resultFailed {
416			fmt.Fprintf(stdout, "原因: %s\n", res.Reason)
417		}
418		fmt.Fprintf(stdout, "发生时间: %s\n", res.Time.Format(timeFmt))
419		return exitOK
420	}
