485	// Handoff 提交一次多件包裹的站点交接。
486	//
487	// 首次提交：所有包裹必须已登记且当前归属源站点，否则整次失败、不作任何改动；
488	// 全部满足时一起改归目的站点并各追加一条交接记录，作为一个整体保存。
489	// 相同请求号且业务内容（源、目的、包裹集合，与顺序无关）相同：直接返回首次结果，
490	// 返回值 replayed 为 true；相同请求号但业务内容不同：报冲突，已有结果不变。
491	func (s *Store) Handoff(request, from, to string, parcels []string, now time.Time) (result *HandoffResult, replayed bool, err error) {
492		if saved, ok := s.data.Handoffs[request]; ok {
493			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
494				return saved, true, nil
495			}
496			return nil, false, fmt.Errorf("请求号 %q 已用于一次不同的交接（源=%q 目的=%q），内容冲突", request, saved.From, saved.To)
497		}
498	
499		// 首次提交：先做全部校验，任何一件不满足都整体失败。
500		for _, id := range parcels {
501			p, ok := s.data.Parcels[id]
502			if !ok {
503				return nil, false, fmt.Errorf("交接失败：包裹 %q 未登记，整次交接未执行", id)
504			}
505			if p.Station != from {
506				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前归属 %q，不属于源站点 %q，整次交接未执行", id, p.Station, from)
507			}
508			if inc := activeFreeze(p); inc != "" {
509				return nil, false, fmt.Errorf("交接失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批交接拒绝，整次交接未执行", id, inc)
510			}
511			if p.Status != statusInStation {
512				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前状态为 %q，不是在站，整次交接未执行", id, p.Status)
513			}
514		}
515	
516		res := &HandoffResult{
517			Request: request,
518			From:    from,
519			To:      to,
520			Parcels: append([]string(nil), parcels...),
521			Time:    now,
522		}
523		s.data.Handoffs[request] = res
524	
525		// 记录旧值，落盘失败时整体回滚。
526		prev := make(map[string]struct {
527			station string
528			trail   []Event
529		}, len(parcels))
530		for _, id := range parcels {
531			p := s.data.Parcels[id]
532			prev[id] = struct {
533				station string
534				trail   []Event
535			}{p.Station, append([]Event(nil), p.Trail...)}
536			p.Station = to
537			p.Status = statusInStation
538			p.Trail = append(p.Trail, Event{
539				Op:      "交接",
540				Station: to,
541				Request: request,
542				Time:    now,
543			})
544		}
545	
546		if err := s.save(); err != nil {
547			delete(s.data.Handoffs, request)
548			for id, old := range prev {
549				p := s.data.Parcels[id]
550				p.Station = old.station
551				p.Trail = old.trail
552			}
553			return nil, false, err
554		}
555		return res, false, nil
556	}
557	
558	// Return 按原交接整批退回：实物送回该交接的源站点，批次与站点取自原交接结果。
559	//
560	// 首次退回：原交接必须存在且尚未成功退回；批次中每件包裹必须仍归属原交接目的站、
561	// 状态为在站，且最后一条流转记录就是该原交接（请求重放不产生新流转，不影响判定）。
562	// 任一条件不满足则整批拒绝，不作任何改动。全部满足时整批改归原交接源站（仍为在站），
563	// 每件按批次顺序追加一条退回记录，原收件、交接轨迹保留不变。
564	// 相同退回请求号且原交接、原因相同：直接返回首次结果，replayed 为 true，
565	// 即使包裹之后又被交接也不重新检查；请求号相同但原交接或原因不同：报冲突。
566	// 退回请求号与交接请求号分属独立去重范围，互不影响；失败的首次退回不占用请求号。
567	func (s *Store) Return(request, handoffReq, reason string, now time.Time) (result *ReturnResult, replayed bool, err error) {
568		if saved, ok := s.data.Returns[request]; ok {
569			if saved.Handoff == handoffReq && saved.Reason == reason {
570				return saved, true, nil
571			}
572			return nil, false, fmt.Errorf("退回请求号 %q 已用于一次不同的退回（原交接=%q 原因=%q），内容冲突",
573				request, saved.Handoff, saved.Reason)
574		}
575	
576		h, ok := s.data.Handoffs[handoffReq]
577		if !ok {
578			return nil, false, fmt.Errorf("退回失败：原交接请求号 %q 不存在", handoffReq)
579		}
580		if h.ReturnedBy != "" {
581			return nil, false, fmt.Errorf("退回失败：原交接 %q 已成功退回（退回请求号 %q），不能再次退回", handoffReq, h.ReturnedBy)
582		}
583	
584		// 先做全部校验，任何一件不满足都整批拒绝。
585		for _, id := range h.Parcels {
586			p, ok := s.data.Parcels[id]
587			if !ok {
588				return nil, false, fmt.Errorf("退回失败：包裹 %q 未登记，整批退回未执行", id)
589			}
590			if inc := activeFreeze(p); inc != "" {
591				return nil, false, fmt.Errorf("退回失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批退回拒绝，整批退回未执行", id, inc)
592			}
593			if p.Station != h.To || p.Status != statusInStation {
594				return nil, false, fmt.Errorf("退回失败：包裹 %q 当前归属 %q、状态 %q，不在原交接目的站 %q 在站，整批退回未执行",
595					id, p.Station, p.Status, h.To)
596			}
597			last := lastFlowEvent(p.Trail)
598			if last.Op != "交接" || last.Request != handoffReq {
599				return nil, false, fmt.Errorf("退回失败：包裹 %q 在原交接 %q 之后又有新的流转，不能退回该交接，整批退回未执行",
600					id, handoffReq)
601			}
602		}
603	
604		res := &ReturnResult{
605			Request: request,
606			Handoff: handoffReq,
607			From:    h.To,
608			To:      h.From,
609			Reason:  reason,
610			Parcels: append([]string(nil), h.Parcels...),
611			Time:    now,
612		}
613		s.data.Returns[request] = res
614		h.ReturnedBy = request
615	
616		// 记录旧值，落盘失败时整体回滚。
617		prev := make(map[string]struct {
618			station string
619			trail   []Event
620		}, len(h.Parcels))
621		for _, id := range h.Parcels {
622			p := s.data.Parcels[id]
623			prev[id] = struct {
624				station string
625				trail   []Event
626			}{p.Station, append([]Event(nil), p.Trail...)}
627			p.Station = h.From
628			p.Status = statusInStation
629			p.Trail = append(p.Trail, Event{
630				Op:         "退回",
631				Station:    h.From,
632				From:       h.To,
633				Request:    request,
634				RefRequest: handoffReq,
635				Reason:     reason,
636				Time:       now,
637			})
638		}
639	
640		if err := s.save(); err != nil {
641			delete(s.data.Returns, request)
642			h.ReturnedBy = ""
643			for id, old := range prev {
644				p := s.data.Parcels[id]
645				p.Station = old.station
646				p.Trail = old.trail
647			}
648			return nil, false, err
649		}
650		return res, false, nil
651	}
652	
653	// Dispatch 提交一次配送批次出站。
654	//
655	// 首次出站：所有包裹必须已登记、当前归属出发站且状态为在站，否则整批拒绝、不作任何改动；
656	// 全部满足时整批转为“配送中”（站点仍记出发站），每件追加一条含批次、配送员和时间的
657	// 出站记录，批次成员按首次提交顺序保存且不可修改。批次号标识一次配送，完成后也不能复用：
658	// 相同批次号且站点、配送员、包裹集合（与顺序无关）相同，直接返回首次结果，replayed 为 true；
659	// 批次号相同但内容不同报冲突；失败的首次出站不占用批次号。
660	func (s *Store) Dispatch(batch, station, courier string, parcels []string, now time.Time) (result *BatchResult, replayed bool, err error) {
661		if saved, ok := s.data.Batches[batch]; ok {
662			if saved.Station == station && saved.Courier == courier && sameSet(saved.Parcels, parcels) {
663				return saved, true, nil
664			}
665			return nil, false, fmt.Errorf("批次号 %q 已用于一次不同的出站（出发站=%q 配送员=%q），内容冲突", batch, saved.Station, saved.Courier)
666		}
667	
668		// 首次出站：先做全部校验，任何一件不满足都整批拒绝。
669		for _, id := range parcels {
670			p, ok := s.data.Parcels[id]
671			if !ok {
672				return nil, false, fmt.Errorf("出站失败：包裹 %q 未登记，整批出站未执行", id)
673			}
674			if p.Station != station {
675				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前归属 %q，不在出发站 %q，整批出站未执行", id, p.Station, station)
676			}
677			if inc := activeFreeze(p); inc != "" {
678				return nil, false, fmt.Errorf("出站失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批出站拒绝，整批出站未执行", id, inc)
679			}
680			if p.Status != statusInStation {
681				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前状态为 %q，不是在站，整批出站未执行", id, p.Status)
682			}
683		}
684	
685		res := &BatchResult{
686			Batch:    batch,
687			Station:  station,
688			Courier:  courier,
689			Parcels:  append([]string(nil), parcels...),
690			Time:     now,
691			Receipts: map[string]*ReceiptEntry{},
692		}
693		s.data.Batches[batch] = res
694	
695		// 记录旧值，落盘失败时整体回滚。
696		prev := make(map[string]struct {
697			status string
698			trail  []Event
699		}, len(parcels))
700		for _, id := range parcels {
701			p := s.data.Parcels[id]
702			prev[id] = struct {
703				status string
704				trail  []Event
705			}{p.Status, append([]Event(nil), p.Trail...)}
706			p.Status = statusDelivering // 站点不变，仍记出发站
707			p.Trail = append(p.Trail, Event{
708				Op:      "出站",
709				Station: station,
710				Batch:   batch,
711				Courier: courier,
712				Time:    now,
713			})
714		}
715	
716		if err := s.save(); err != nil {
717			delete(s.data.Batches, batch)
718			for id, old := range prev {
719				p := s.data.Parcels[id]
720				p.Status = old.status
721				p.Trail = old.trail
722			}
723			return nil, false, err
724		}
725		return res, false, nil
726	}
727	
728	// Receipt 提交一件包裹在某个配送批次下的回执。
729	//
730	// 首次回执：批次必须存在，包裹必须属于该批次、尚未在该批次回执，且当前仍在该批次
731	// 配送中；任一不满足则拒绝，不作任何改动。签收后状态为“已签收”；失败表示实物已回到
732	// 出发站，恢复“在站”，可加入新的配送批次。两种结果都保留站点并追加一条含批次、结果、
733	// 原因（失败时）、请求号和时间的回执记录；全部成员回执后批次自动完成。
734	// 相同回执请求号且批次、包裹、结果、清理后的原因相同：直接返回首次结果，replayed 为
735	// true，不重新检查当前状态，即使失败包裹已进入新批次；请求号相同但内容不同报冲突。
736	// 回执请求号与批次号、包裹编号、交接及退回请求号分属独立去重范围，允许同名；
737	// 失败的首次回执不占用请求号。
738	func (s *Store) Receipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, err error) {
739		res, replayed, undo, err := s.applyReceipt(request, batch, parcel, result, reason, now)
740		if err != nil || replayed {
741			return res, replayed, err
742		}
743		if err := s.save(); err != nil {
744			undo() // 落盘失败：回滚内存变更，保留原有有效数据
745			return nil, false, err
746		}
747		return res, false, nil
748	}
749	
750	// applyReceipt 在内存台账上校验并应用一条回执（不落盘），是 Receipt 与
751	// ImportReceipts 共用的核心。全部校验通过后才会改动数据；返回的 undo 可在
752	// 整体保存失败时撤销本次改动（重放或校验失败时 undo 为 nil）。
753	func (s *Store) applyReceipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, undo func(), err error) {
754		if saved, ok := s.data.Receipts[request]; ok {
755			if saved.Batch == batch && saved.Parcel == parcel && saved.Result == result && saved.Reason == reason {
756				return saved, true, nil, nil
757			}
758			return nil, false, nil, fmt.Errorf("回执请求号 %q 已用于一次不同的回执（批次=%q 包裹=%q 结果=%q），内容冲突",
759				request, saved.Batch, saved.Parcel, saved.Result)
760		}
761	
762		b, ok := s.data.Batches[batch]
763		if !ok {
764			return nil, false, nil, fmt.Errorf("回执失败：批次号 %q 不存在", batch)
765		}
766		member := false
767		for _, id := range b.Parcels {
768			if id == parcel {
769				member = true
770				break
771			}
772		}
773		if !member {
774			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 不属于批次 %q", parcel, batch)
775		}
776		if _, done := b.Receipts[parcel]; done {
777			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 在批次 %q 中已回执，每件在一个批次只能成功回执一次", parcel, batch)
778		}
779		p := s.data.Parcels[parcel] // 批次成员必已登记（载入校验保证）
780		if p.Status != statusDelivering || currentBatch(p) != batch {
781			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 当前状态为 %q，不在批次 %q 配送中", parcel, p.Status, batch)
782		}
783	
784		res = &ReceiptResult{
785			Request: request,
786			Batch:   batch,
787			Parcel:  parcel,
788			Result:  result,
789			Reason:  reason,
790			Time:    now,
791		}
792		entry := &ReceiptEntry{Request: request, Result: result, Reason: reason, Time: now}
793	
794		// 记录旧值，undo 在整体落盘失败时回滚。
795		oldStatus, oldStation := p.Status, p.Station
796		oldTrailLen := len(p.Trail)
797	
798		if result == resultSigned {
799			p.Status = statusSigned // 站点保留不变
800		} else {
801			p.Status = statusInStation // 实物已回到出发站，可加入新的配送批次
802			p.Station = b.Station
803		}
804		p.Trail = append(p.Trail, Event{
805			Op:      "回执",
806			Station: p.Station,
807			Batch:   batch,
808			Result:  result,
809			Reason:  reason,
810			Request: request,
811			Time:    now,
812		})
813		b.Receipts[parcel] = entry
814		s.data.Receipts[request] = res
815	
816		undo = func() {
817			delete(s.data.Receipts, request)
818			delete(b.Receipts, parcel)
819			p.Status, p.Station = oldStatus, oldStation
820			p.Trail = p.Trail[:oldTrailLen]
821		}
822		return res, false, undo, nil
823	}
824	
825	// ReceiptImportRecord 是回执整批导入文件中的一条记录（已清洗）。
826	type ReceiptImportRecord struct {
827		Request string // 回执请求号（与逐件 receipt 共用去重范围）
828		Batch   string // 配送批次号
829		Parcel  string // 包裹编号
830		Result  string // 签收 | 失败
831		Reason  string // 失败原因（失败时非空，签收时为空）
832	}
833	
834	// ReceiptImportItem 是整批导入中一条记录的处理结果，按文件顺序排列。
835	type ReceiptImportItem struct {
836		Record   ReceiptImportRecord // 清洗后的记录内容
837		Time     time.Time           // 发生时间（重放时为首次保存的时间）
838		Replayed bool                // true 表示同内容历史重放，未产生新变更
839	}
840	
841	// ImportReceipts 按文件顺序整批应用回执记录。
842	//
843	// 逐条处理：与逐件 Receipt 共用同一回执请求号去重范围，同请求号且批次、包裹、
844	// 结果、清理后的原因相同的记录返回首次结果与时间（重放），不检查当前状态、不追加
845	// 轨迹、不改变批次进度；换内容报冲突。首次回执要求批次存在、包裹属于该批次、
846	// 尚未在该批次回执且当前仍在该批次配送中（含本文件前面记录已产生的回执）。
847	// 全部记录可接受时作为一个整体原子落盘；任一记录无效、冲突或受理条件不符，
848	// 整份拒绝并提示记录位置，台账保持导入前状态，新请求号均不占用。
849	// 全部为历史重放时不改写台账。
850	func (s *Store) ImportReceipts(records []ReceiptImportRecord, now time.Time) ([]ReceiptImportItem, error) {
851		// 在台账副本上按文件顺序试算：任一记录失败直接放弃副本，原台账保持不变。
852		work, err := s.fork()
853		if err != nil {
854			return nil, err
855		}
856		items := make([]ReceiptImportItem, 0, len(records))
857		hasNew := false
858		for i, rec := range records {
859			res, replayed, _, err := work.applyReceipt(rec.Request, rec.Batch, rec.Parcel, rec.Result, rec.Reason, now)
860			if err != nil {
861				return nil, fmt.Errorf("第 %d 条记录（请求号 %q）：%w", i+1, rec.Request, err)
862			}
863			if !replayed {
864				hasNew = true
865			}
866			items = append(items, ReceiptImportItem{Record: rec, Time: res.Time, Replayed: replayed})
867		}
868		if !hasNew {
869			return items, nil // 全部为历史重放：不改写台账
870		}
871	
872		// 整体提交：副本替换当前台账后一次原子落盘，失败时恢复导入前状态。
873		orig := s.data
874		s.data = work.data
875		if err := s.save(); err != nil {
876			s.data = orig
877			return nil, err
878		}
879		return items, nil
880	}
881	
882	// fork 返回当前台账的深拷贝副本，供整批导入试算；副本上的任何改动都不影响原台账。
883	func (s *Store) fork() (*Store, error) {
884		buf, err := json.Marshal(s.data)
885		if err != nil {
886			return nil, fmt.Errorf("准备回执整批导入失败: %w", err)
887		}
888		var cp ledgerFile
889		if err := json.Unmarshal(buf, &cp); err != nil {
890			return nil, fmt.Errorf("准备回执整批导入失败: %w", err)
891		}
892		return &Store{path: s.path, data: cp}, nil
893	}
894	
895	// Freeze 对一件在站包裹登记异常冻结。
896	//
897	// 首次冻结：包裹必须已登记、当前归属指定站点且状态为在站；配送中、已签收或已冻结的
898	// 包裹不能冻结。成功后站点不变，状态转为异常冻结，追加一条含异常单号、原因、站点和
899	// 时间的冻结记录。一件包裹同时只能有一张未解除异常单。
900	// 冻结只是管理记录，不移动实物、不算新流转。
901	// 异常单号标识一次异常，解除后也不能复用：相同异常单号且包裹、站点、清理后的原因
902	// 相同，直接返回首次冻结结果与时间，replayed 为 true，不再次冻结（即使该异常单已解除、
903	// 包裹已发生新的流转，也不检查当前状态）；异常单号相同但内容不同报冲突；
904	// 失败的首次冻结不占用异常单号。异常单号与包裹编号及其他业务编号分属独立去重范围。
905	func (s *Store) Freeze(incident, parcel, station, reason string, now time.Time) (res *FreezeResult, replayed bool, err error) {
906		if saved, ok := s.data.Freezes[incident]; ok {
907			if saved.Parcel == parcel && saved.Station == station && saved.Reason == reason {
908				return saved, true, nil
909			}
910			return nil, false, fmt.Errorf("异常单号 %q 已用于一次不同的冻结（包裹=%q 站点=%q 原因=%q），内容冲突",
911				incident, saved.Parcel, saved.Station, saved.Reason)
912		}
913	
914		p, ok := s.data.Parcels[parcel]
915		if !ok {
916			return nil, false, fmt.Errorf("冻结失败：包裹 %q 未登记，冻结未执行", parcel)
917		}
918		if p.Station != station {
919			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前归属 %q，不在指定站点 %q，冻结未执行", parcel, p.Station, station)
920		}
921		if p.Status != statusInStation {
922			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前状态为 %q，仅在站包裹可以冻结，冻结未执行", parcel, p.Status)
923		}
924	
925		res = &FreezeResult{
926			Incident: incident,
927			Parcel:   parcel,
928			Station:  station,
929			Reason:   reason,
930			Time:     now,
931		}
932		s.data.Freezes[incident] = res
933	
934		// 记录旧值，落盘失败时整体回滚。
935		oldStatus := p.Status
936		oldTrail := append([]Event(nil), p.Trail...)
937		p.Status = statusFrozen // 站点不变
938		p.Trail = append(p.Trail, Event{
939			Op:       "冻结",
940			Station:  station,
941			Incident: incident,
942			Reason:   reason,
943			Time:     now,
944		})
945	
946		if err := s.save(); err != nil {
947			delete(s.data.Freezes, incident)
948			p.Status, p.Trail = oldStatus, oldTrail
949			return nil, false, err
950		}
951		return res, false, nil
952	}
953	
954	// Unfreeze 解除一件包裹当前的异常冻结。
955	//
956	// 首次解除：异常单必须存在且尚未解除，并且仍是该包裹当前冻结对应的异常单；
957	// 异常单不存在、已解除或对应关系不符均拒绝。成功后包裹在原站恢复在站，原异常单
958	// 永久标记为已解除（异常单号不得复用），追加一条含异常单号、解除请求号、处理说明及
959	// 时间的解除记录，原冻结记录不删改；之后可用新异常单再次冻结。
960	// 解除只是管理记录，不移动实物、不算新流转。
961	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名：相同解除请求号且异常单、
962	// 处理说明相同，直接返回首次解除结果与时间，replayed 为 true，不检查当前状态，也不影响
963	// 后来新建的异常单或后续流转；请求号相同但内容不同报冲突；失败的首次解除不占用请求号。
964	func (s *Store) Unfreeze(request, incident, note string, now time.Time) (res *UnfreezeResult, replayed bool, err error) {
965		if saved, ok := s.data.Unfreezes[request]; ok {
966			if saved.Incident == incident && saved.Note == note {
967				return saved, true, nil
968			}
969			return nil, false, fmt.Errorf("解除请求号 %q 已用于一次不同的解除（异常单=%q 处理说明=%q），内容冲突",
970				request, saved.Incident, saved.Note)
971		}
972	
973		f, ok := s.data.Freezes[incident]
974		if !ok {
975			return nil, false, fmt.Errorf("解除失败：异常单号 %q 不存在，解除未执行", incident)
976		}
977		if f.ReleasedBy != "" {
978			return nil, false, fmt.Errorf("解除失败：异常单 %q 已解除（解除请求号 %q），不能重复解除", incident, f.ReleasedBy)
979		}
980		p, ok := s.data.Parcels[f.Parcel]
981		if !ok {
982			return nil, false, fmt.Errorf("解除失败：异常单 %q 对应的包裹 %q 不存在，解除未执行", incident, f.Parcel)
983		}
984		if p.Status != statusFrozen || activeFreeze(p) != incident {
985			return nil, false, fmt.Errorf("解除失败：异常单 %q 不是包裹 %q 当前冻结对应的异常单（当前异常单 %q），解除未执行",
986				incident, f.Parcel, activeFreeze(p))
987		}
988	
989		res = &UnfreezeResult{
990			Request:  request,
991			Incident: incident,
992			Parcel:   f.Parcel,
993			Note:     note,
994			Time:     now,
995		}
996		s.data.Unfreezes[request] = res
997		f.ReleasedBy = request
998	
999		// 记录旧值，落盘失败时整体回滚。
1000		oldStatus := p.Status
1001		oldTrail := append([]Event(nil), p.Trail...)
1002		p.Status = statusInStation // 在原站恢复在站，站点不变
1003		p.Trail = append(p.Trail, Event{
1004			Op:       "解除冻结",
1005			Station:  f.Station,
1006			Incident: incident,
1007			Request:  request,
1008			Note:     note,
1009			Time:     now,
1010		})
1011	
1012		if err := s.save(); err != nil {
1013			delete(s.data.Unfreezes, request)
1014			f.ReleasedBy = ""
1015			p.Status, p.Trail = oldStatus, oldTrail
1016			return nil, false, err
1017		}
1018		return res, false, nil
1019	}
1020	
1021	// currentBatch 返回包裹当前配送中的批次号（最后一条出站记录的批次）；不在配送中返回空。
1022	func currentBatch(p *Parcel) string {
1023		for i := len(p.Trail) - 1; i >= 0; i-- {
1024			if p.Trail[i].Op == "出站" {
1025				return p.Trail[i].Batch
1026			}
1027		}
1028		return ""
1029	}
1030	
1031	// activeFreeze 返回包裹当前未解除冻结对应的异常单号；未冻结返回空。
1032	// 冻结状态与轨迹成对追加，故当前状态为异常冻结时最后一条冻结记录即为当前异常单。
1033	func activeFreeze(p *Parcel) string {
1034		if p.Status != statusFrozen {
1035			return ""
1036		}
1037		for i := len(p.Trail) - 1; i >= 0; i-- {
1038			if p.Trail[i].Op == "冻结" {
1039				return p.Trail[i].Incident
1040			}
1041		}
1042		return ""
1043	}
1044	
1045	// lastFlowEvent 返回轨迹中最后一条真实流转记录（交接/退回/出站/回执）。
1046	// 冻结与解除只是管理记录，不算新流转，判定旧交接可否退回时须跳过它们。
1047	func lastFlowEvent(trail []Event) Event {
1048		for i := len(trail) - 1; i >= 0; i-- {
1049			switch trail[i].Op {
1050			case "冻结", "解除冻结":
1051				continue
1052			default:
1053				return trail[i]
1054			}
1055		}
1056		return Event{}
1057	}
1058	
1059	// BatchQuery 返回一个配送批次的出站结果与逐件回执进度；批次不存在时报错。
1060	func (s *Store) BatchQuery(batch string) (*BatchResult, error) {
1061		b, ok := s.data.Batches[batch]
1062		if !ok {
1063			return nil, fmt.Errorf("批次 %q 不存在", batch)
1064		}
1065		return b, nil
1066	}
1067	
1068	// sameSet 判断两个包裹列表作为集合是否相同（顺序不影响判定）。
1069	func sameSet(a, b []string) bool {
1070		if len(a) != len(b) {
1071			return false
1072		}
1073		x := append([]string(nil), a...)
1074		y := append([]string(nil), b...)
1075		sort.Strings(x)
1076		sort.Strings(y)
1077		for i := range x {
1078			if x[i] != y[i] {
1079				return false
1080			}
1081		}
1082		return true
1083	}
1084	
1085	// save 将当前台账作为一个整体原子写入数据文件：先写临时文件并同步，
1086	// 校验可重新解析后再原子替换，最后目录同步，避免保存失败留下部分业务变更。
1087	func (s *Store) save() error {
1088		if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil {
1089			return fmt.Errorf("保存数据文件失败: %w", err)
1090		}
1091		buf, err := json.MarshalIndent(s.data, "", "  ")
1092		if err != nil {
1093			return fmt.Errorf("保存数据文件失败: %w", err)
1094		}
1095		buf = append(buf, '\n')
1096	
1097		tmp, err := os.CreateTemp(filepath.Dir(s.path), ".parcelhub-*.tmp")
1098		if err != nil {
1099			return fmt.Errorf("保存数据文件失败: %w", err)
1100		}
1101		tmpName := tmp.Name()
1102		cleanup := func() { _ = os.Remove(tmpName) }
1103	
1104		if _, err := tmp.Write(buf); err != nil {
1105			_ = tmp.Close()
1106			cleanup()
1107			return fmt.Errorf("保存数据文件失败: %w", err)
1108		}
1109		if err := tmp.Sync(); err != nil {
1110			_ = tmp.Close()
1111			cleanup()
1112			return fmt.Errorf("保存数据文件失败: %w", err)
1113		}
1114		if err := tmp.Close(); err != nil {
1115			cleanup()
1116			return fmt.Errorf("保存数据文件失败: %w", err)
1117		}
1118	
1119		// 替换前确认临时文件自身可解析，杜绝把损坏内容写到正式位置。
1120		var check ledgerFile
1121		if err := json.Unmarshal(buf, &check); err != nil {
1122			cleanup()
1123			return fmt.Errorf("保存数据文件失败: 写入内容无效: %w", err)
1124		}
1125	
1126		if err := os.Rename(tmpName, s.path); err != nil {
1127			cleanup()
1128			return fmt.Errorf("保存数据文件失败: %w", err)
1129		}
1130		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
1131			_ = dir.Sync()
1132			_ = dir.Close()
1133		}
1134		return nil
1135	}
1136

