// sameList 判断两个字符串列表是否逐项相同（顺序影响判定）。
func sameList(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

