		headline, res.Request, res.Batch, res.Station, res.Reason, len(res.Parcels))
	for _, id := range res.Parcels {
		fmt.Fprintf(stdout, "  - %s\n", id)
	}
	fmt.Fprintf(stdout, "发生时间: %s\n", res.Time.Format(timeFmt))
	return exitOK
}

