func TestAbortCountsAsNewFlowForReturn(t *testing.T) {
	s, _ := openTempStore(t)
	t0 := tClock(2026, 10, 5, 9, 0)
	mustRegister(t, s, "P001", "站点A", t0)
	if _, _, err := s.Handoff("H1", "站点A", "站点B", []string{"P001"}, t0.Add(time.Hour)); err != nil {
		t.Fatalf("交接意外失败: %v", err)
